        with open(file,"r") as r:
            lines = r.readlines()
        with open(file,"w") as w:
            for num,line in enumerate(lines):
                if num >= digit:
                    w.write(line)
        p(" [•] File  Complete")
        input(" [•] Press Enter to go back ")
        iAmMain().iAmMenu()
